tool.command:
set -o pipefail;
#if $wget: ## Asked for wget, we assume there's a certificate problem on (at least) one ## of the many requested servers, force disable of all checks echo "check_certificate = off" > \$HOME/.wgetrc && #end if
funannotate setup -d '$output_file.extra_files_path' #if $partial_data -i merops -b eukaryota #else -b all #end if $wget && awk ' BEGIN { FS = OFS = "\t"; valid = 1; records = 0 } NF != 7 { valid = 0; next } { print \$1, \$2, \$4, \$6, \$7; records++ } END { if (!valid || records == 0) exit 1 } ' '$output_file.extra_files_path/funannotate-db-info.txt' | LC_ALL=C sort > 'funannotate.canonical.manifest' && funannotate_digest_line=\$(sha256sum 'funannotate.canonical.manifest') && funannotate_digest="\${funannotate_digest_line%% *}" && if [[ ! "\$funannotate_digest" =~ ^[0-9a-f]{64}\$ ]]; then exit 1; fi && sed "s/__FUNANNOTATE_SHA256__/\$funannotate_digest/g" '$dmjson' > '$output_file'

configfiles.configfile:
#slurp
#import json
#set value = "funannotate-@TOOL_VERSION@-__FUNANNOTATE_SHA256__"
{
  "data_tables": {
    "funannotate": [
      {
        "value": #echo json.dumps($value)#,
        "description": #echo json.dumps("Funannotate database " + $value)#,
        "format_version": "1.0",
        "path": #echo json.dumps($value)#
      }
    ]
  }
}
